import React, { useEffect, useState } from 'react';
import { Box, Button, TextField, Typography, Modal, Switch } from '@mui/material';
import SearchableDropdown from '../../FlowBuilder/Common/SearchableDropdown/SearchableDropdown.tsx';
import { ConstantActions, ManagementActions } from '../../../Services/_actions';
import { ProfileObject } from '../../../interfaces/Management.interface.ts';
import { useRecoilState, useRecoilValue } from 'recoil';
import { profileObjAtom } from '../../../Services/_states/Management/management.ts';
import { useNavigate, useParams } from 'react-router-dom';
import { userInformationAtom } from '../../../Services/_states/auth.js';
import ObjectLevelPermission from './ObjectLevelPermission.tsx';
import GeneralUserLevelPermission from './GeneralUserLevelPermission.tsx';
import LoadingButton from '../../Shared/Loading/index.tsx';
import { useSnackBar } from '../../FlowBuilder/Common/SnackBar/index.tsx';
import OrganisationDropdown from '../../Shared/OrganisationDropdown/index.tsx';
interface CreateEditProfileFormModalProps {
  open: boolean;
  mode: string;
  onClose: (data: any | null) => void;
}


const CreateEditProfileForm: React.FC<CreateEditProfileFormModalProps> = ({ open, mode, onClose }) => {
  const constantActions = ConstantActions();
  const actions = ManagementActions();
  const { showSnackBar } = useSnackBar();
  const loggedInUser = useRecoilValue(userInformationAtom);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();
  const [profileObject, setProfileObject] = useRecoilState<ProfileObject | any>(profileObjAtom);
  // const { mode } = useParams();
  const [contentTypes, setContentTypes] = useState([]);
  const [formData, setFormData] = useState<ProfileObject>({
    name: '',
    organisation: '',
    is_standard: false,
  });
  const [validationErrors, setValidationErrors] = useState({
    name: '',
    organisation: '',
  });

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setIsLoading(true);
    const errors: any = {};

    if (!formData?.name?.trim()) {
      errors.name = 'Profile name is required';
    }

    if (!formData.organisation) {
      errors.organisation = 'Organisation is required';
    }

    setValidationErrors(errors);

    if (Object.keys(errors).length === 0) {
      if (mode === 'edit') {
        try {
          let updateObj = {
            ...formData,
            organisation: formData?.organisation?.organisation_id,
          };
          const res: any = await actions.updateProfile(updateObj, updateObj?.id);
          if (res?.status === 200) {
            showSnackBar('Profile Updated successfully.', 'success');
            // navigate("/r/management/profile-list/");
            onClose({...formData});
          }
          setIsLoading(false);
        } catch (error) {
          showSnackBar('An error occurred while Updating the profile.', 'error');
        }
      } else {
        let generalUserPermission: any = [];
        for (let id in loggedInUser?.profile?.general_user_permission) {
          let row: any = { ...loggedInUser?.profile?.general_user_permission[id] };
          delete row['id'];
          row['is_allowed'] = '';
          generalUserPermission.push(row);
        }
        let updateObj = {
          ...formData,
          general_user_permission: generalUserPermission,
          organisation: formData?.organisation?.organisation_id,
        };
        try {
          const res = await actions.createProfile(updateObj);
          if (res?.status === 200) {
            setProfileObject({ ...res?.data?.data });
            let profileData = { ...res?.data?.data };

            for (var x in contentTypes) {
              var contentType: { model: string; id: any } = contentTypes[x];

              var object_level_permission1 = {
                name: contentType?.model?.toUpperCase(),
                content_type: contentType?.id,
                profile: profileData?.id,
              };
              let objRes: any = await actions.createObjectLevelPermission(object_level_permission1);
              if (!profileData?.object_level_permission)
                profileData['object_level_permission'] = [];
              profileData = {
                ...profileData,
                object_level_permission: [
                  ...profileData?.object_level_permission,
                  { ...objRes?.data?.data },
                ],
              };
            }
            setProfileObject({ ...profileData });
            setIsLoading(false);
            onClose({ ...profileData });
            showSnackBar('Profile Created successfully.', 'success');
            navigate("/r/management/profile-permissions/edit")
          }
        } catch (error) {
          showSnackBar('An error occurred while Updating the profile.', 'error');

        }
      }
    }
    setIsLoading(false);
  };
  const fetchContents = async () => {
    try {
      let res = await actions.getContentTypes();
      if (res?.status === 200) {
        setContentTypes(res?.data || []);
      }
    } catch (error) {
      showSnackBar('An error occurred while fetching api.', 'error');
      throw error;
    }
  };

  // useEffect(() => {
  //   if (organisationList?.length === 1) {
  //     setFormData({
  //       ...profileObject,
  //       organisation: { ...organisationList[0], label: organisationList[0]?.name },
  //       is_standard: profileObject?.is_standard,
  //       name: profileObject?.name,
  //     });
  //   };
  // }, [organisationList])

  useEffect(() => {
    fetchContents();
  }, []);

  useEffect(() => {
    if (mode === 'edit' || mode === 'view') {
      if (!profileObject?.id) {
        navigate(-1);
      }
      setFormData({
        ...profileObject,
        // organisation: { ...profileObject?.organisation, label: profileObject?.organisation?.name },
        // is_standard: profileObject?.is_standard,
        // name: profileObject?.name,
      });
    }
  }, []);

  return (
    <>
      <Modal open={open} onClose={() => { onClose(null) }}>
        <Box
          sx={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            bgcolor: 'background.paper',
            boxShadow: 24,
            borderRadius: '8px',
            p: 3,
            width: 400,
            maxHeight: '90vh',
            overflowY: 'auto',
          }}
        >

          {/* <Box
        sx={{
          maxWidth: '500px',
          // margin: '0 auto',
          padding: '24px',
          border: '1px solid #ddd',
          borderRadius: '8px',
          backgroundColor: '#f9f9f9',
        }}
      > */}
          <Typography variant="h6" fontWeight="bold" gutterBottom textAlign="left">
            {`${mode === 'edit' ? 'Update' : mode === 'view' ? 'View' : 'Create'} Profile`}
          </Typography>
          {/* <SearchableDropdown
          label={
            <Typography component="span">
              Organization <span style={{ color: 'red' }}>*</span>
            </Typography>
          }
          options={
            organisationList?.length > 0
              ? organisationList.map((org: any) => ({
                ...org,
                label: org?.name,
                value: org.organisation_id,
              }))
              : [{ label: 'No Organization', value: '' }]
          }
          value={formData?.organisation || null}
          onChange={(data) => {
            setFormData({ ...formData, organisation: data });
            setValidationErrors({ ...validationErrors, organisation: '' });
          }}
          error={!!validationErrors.organisation}
          errorMessage={validationErrors.organisation}
          sx={{ mb: 2 }}
          getOptionDisabled={(option) => option.value === ''}
          // disabled={organisationList?.length === 1}
          disabled={mode === 'view' || organisationList?.length === 1}
        /> */}
          <OrganisationDropdown
            label={
              <Typography component="span">
                Organization <span style={{ color: 'red' }}>*</span>
              </Typography>
            }
            value={formData?.organisation || null}
            onChange={(data) => {
              setFormData({ ...formData, organisation: data });
              setValidationErrors({ ...validationErrors, organisation: '' });
            }}
            error={!!validationErrors.organisation}
            errorMessage={validationErrors.organisation}
            disabled={mode === 'view'}
          />

          <TextField
            label={
              <Typography component="span">
                Profile Name <span style={{ color: 'red' }}>*</span>
              </Typography>
            }
            fullWidth
            value={formData?.name || ''}
            onChange={(e) => {
              setFormData({ ...formData, name: e.target.value });
              setValidationErrors({ ...validationErrors, name: '' });
            }}
            sx={{ mb: 2 }}
            margin="dense"
            variant="outlined"
            size="small"
            error={!!validationErrors?.name}
            helperText={validationErrors?.name}
            disabled={mode === 'view'}
          />
          <Box display="flex" alignItems="center" justifyContent="space-between" sx={{ mb: 3 }}>
            <Typography>Is Standard</Typography>
            <Switch
              checked={formData?.is_standard || false}
              onChange={(e) => {
                setFormData({ ...formData, is_standard: e.target.checked });
              }}
              inputProps={{ 'aria-label': 'Is Standard Profile' }}
              disabled={mode === 'view'}
            />
          </Box>
          <Box mt={3} display="flex" justifyContent="flex-end" gap={2}>
            <Button variant="outlined" size="small" onClick={()=>{onClose(null)}} disabled={mode === 'view'}>
              Cancel
            </Button>
            {mode !== 'view' && (
              <LoadingButton
                buttonName={mode === 'edit' ? 'Update' : 'Create'}
                variant="contained"
                onClickButton={(e: React.FormEvent<HTMLFormElement>) => handleSubmit(e)}
                isLoading={isLoading}
                size='small'
              />
            )}
          </Box>
        </Box>
      </Modal>
    </>
  );
};
export default CreateEditProfileForm;
